#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,k;scanf("%d %d",&n,&k);
priority_queue<long long>pq;long long total=0;
for(int i=0;i<n;++i){long long x;scanf("%lld",&x);
pq.push(x);
if((int)pq.size()>k)total+=pq.top(),pq.pop();}
printf("%lld\n",total);return 0;}

